#include "KS/SRC/ks/FEMenu_shared.h"
#include "KS/SRC/ks/igo_widget_shared.h"

struct MemCard {
    int free;
    bool exists;
    bool changed;
    bool available;
    bool ask_format;
    bool saved_games;
    int status;
};

class Career {
public:
    int GetSurferIdx();
};

class SaveLoadFrontEnd {
    char padding[0x32c4];
    int dstate;
public:
    int GetDState() { return dstate; }
    enum { DSTATE_SAVE = 7 };
};

class GenericGameSaver {
public:
    static GenericGameSaver *inst();
    stringx getInsertCardString(int card, int slot);
};

class NamesMenu : public FEMultiMenu {
    char padding0[0x164 - sizeof(FEMultiMenu)];
    bool save;
    char padding1[0x170 - 0x165];
    SaveLoadFrontEnd *sl_parent;
    char padding2[0x1c0 - 0x174];
    MemCard cards[2];
    stringx blank_name;
    int active_card;
    int adjusted_active_card;
    char padding3[0x290 - 0x204];
    BoxText *message;
    char padding4[0x2a4 - 0x294];
    bool draw_message;
public:
    void UpdateMessage();
private:
    void TurnPQLines(bool on);
};

extern Career *g_career;
extern stringx ksGlobalTextArray[];
extern GenericGameSaver *generic_game_saver;

enum { SURFER_LAST = 14, GT_FE_MENU_NO_CAREER = 108, GT_FE_MENU_NO_SAVED_GAMES = 118 };

__asm__(".equ g_career, 0x00427C9C");
__asm__(".equ ksGlobalTextArray, 0x003E6050");
__asm__(".equ generic_game_saver, 0x0041E5B8");
__asm__(".equ GetSurferIdx__6Career, 0x0025A7C0");
__asm__(".equ getInsertCardString__16GenericGameSaverii, 0x001E6628");
__asm__(".equ TurnPQLines__9NamesMenub, 0x0019ED70");

GenericGameSaver *GenericGameSaver::inst()
{
    return generic_game_saver;
}

void NamesMenu::UpdateMessage()
{
	draw_message = true;
	if(g_career->GetSurferIdx() == SURFER_LAST && sl_parent->GetDState()== SaveLoadFrontEnd::DSTATE_SAVE)
	{
		message->changeText(ksGlobalTextArray[GT_FE_MENU_NO_CAREER]);

	}
	else if(cards[adjusted_active_card].exists)
	{
		if(!save && !cards[adjusted_active_card].saved_games)
			message->changeText(ksGlobalTextArray[GT_FE_MENU_NO_SAVED_GAMES]);
		else 
			draw_message = false;
	}
	else 
		message->changeText(GenericGameSaver::inst()->getInsertCardString(active_card==-1?-1:active_card/2, active_card==-1?0:active_card%2));
	if(draw_message) 
		message->makeBox(240, 75, false, -1, 17);
	TurnPQLines(!draw_message);
}
